from lightlag_surface import Surface, PHYSICS, TERRAIN_CODES

with open("/tmp/opencode/map0.json") as f:
    world = json.load(f)
with open("/tmp/opencode/rules.json") as f:
    rules = json.load(f)

print("Base:", world["base"])
surf = Surface(world["cell_m"], world["elevation_cm"], world["terrain"])
print(f"Grid size: nx={surf.nx}, ny={surf.ny}, width={surf.width}, height={surf.height}")

# Check steep cells
steep_cells = 0
for j in range(surf.ny - 1):
    for i in range(surf.nx - 1):
        if surf.cell_max_slope(i, j) > PHYSICS["max_tilt"]:
            steep_cells += 1
print(f"Cells with max_slope > 0.36: {steep_cells} / {(surf.nx-1)*(surf.ny-1)}")

# Print ASCII map of terrain and steep slopes (downsampled or full 120x80)
# 120x80 fits nicely in terminal! Let's print 120x80 with targets and base marked.
grid_chars = [[" " for _ in range(surf.nx - 1)] for _ in range(surf.ny - 1)]
for j in range(surf.ny - 1):
    for i in range(surf.nx - 1):
        ms = surf.cell_max_slope(i, j)
        code = surf.codes[j][i]
        if ms > 0.36:
            grid_chars[j][i] = "#"
        elif ms > 0.28:
            grid_chars[j][i] = "^"
        else:
            if code == "s":
                grid_chars[j][i] = "."
            elif code == "k":
                grid_chars[j][i] = ":"
            elif code == "b":
                grid_chars[j][i] = "_"
            else:
                grid_chars[j][i] = " "

bx, by = world["base"]["x"], world["base"]["y"]
bi, bj, _, _ = surf.locate(bx, by)
grid_chars[bj][bi] = "B"

for t in world["targets"]:
    ti, tj, _, _ = surf.locate(t["x"], t["y"])
    grid_chars[tj][ti] = str(int(t["value"]))

print("\nMAP (y from top=395 to bottom=0, x from 0 to 595):")
print("Legend: # = slope>0.36, ^ = slope>0.28, . = sand, : = rocks, _ = bedrock, space = regolith, B = base, 1-5 = target value")
for j in range(surf.ny - 2, -1, -1):
    if j % 2 == 0:
        print(f"{j*5:3d} |" + "".join(grid_chars[j]) + "|")

