class PathPlanner:
    def __init__(self, surf: Surface):
        self.surf = surf
        self.step = 5.0
        self.nx = int(surf.width // self.step) + 1
        self.ny = int(surf.height // self.step) + 1
        self.mean_slip = {k: 0.5 * (v[0] + v[1]) for k, v in PHYSICS["slip_base_ranges"].items()}
        self.offsets = [(0.0, 0.0)]
        for r in (1.75, 3.5):
            for a in range(8):
                ang = a * math.pi / 4.0
                self.offsets.append((r * math.cos(ang), r * math.sin(ang)))
        self._build_graph()
        self._dijkstra_cache = {}

    def is_segment_safe(self, x1, y1, x2, y2, max_slope=0.28):
        dist = math.hypot(x2 - x1, y2 - y1)
        if dist < 1e-6:
            return True
        n_s = max(2, int(math.ceil(dist / 0.5)))
        for k in range(n_s + 1):
            f = k / n_s
            x = x1 + (x2 - x1) * f
            y = y1 + (y2 - y1) * f
            if not (4.0 <= x <= self.surf.width - 4.0 and 4.0 <= y <= self.surf.height - 4.0):
                return False
            for ox, oy in self.offsets:
                _, gx, gy, _ = self.surf.sample(x + ox, y + oy)
                if math.hypot(gx, gy) > max_slope:
                    return False
        return True

    def edge_cost(self, x1, y1, x2, y2, max_slope=0.28):
        dist = math.hypot(x2 - x1, y2 - y1)
        n_s = max(4, int(math.ceil(dist / 0.5)))
        ux, uy = (x2 - x1) / dist, (y2 - y1) / dist
        ds = dist / n_s
        total = 0.0
        for k in range(n_s):
            f = (k + 0.5) / n_s
            x = x1 + (x2 - x1) * f
            y = y1 + (y2 - y1) * f
            if not (4.0 <= x <= self.surf.width - 4.0 and 4.0 <= y <= self.surf.height - 4.0):
                return math.inf
            local_max = 0.0
            for ox, oy in self.offsets:
                _, gx0, gy0, _ = self.surf.sample(x + ox, y + oy)
                s = math.hypot(gx0, gy0)
                if s > max_slope:
                    return math.inf
                if s > local_max:
                    local_max = s
            _, gx, gy, code = self.surf.sample(x, y)
            tname = TERRAIN_CODES[code]
            grade = gx * ux + gy * uy
            slip = min(0.9, max(0.0, self.mean_slip[tname] + PHYSICS["slip_grade_gain"][tname] * max(0.0, grade)))
            speed = 5.0 * (1.0 - slip)
            risk_mult = 1.0 + 0.4 * max(0.0, (local_max - 0.18) / 0.10) ** 2
            total += (ds / speed) * risk_mult
        return total
